<script setup>
import {onShow,onHide} from '@dcloudio/uni-app';
import {store,refresh,clearState} from './services/store';
import {request,token} from './services/api';
let timer;let pending=false;let foreground=false;
async function heartbeat(){if(!foreground||pending||!token()||!store.room)return;pending=true;try{const data=await request('/rooms/heartbeat','POST',{});store.room=data.room;}catch(error){if(error.status===404)store.room=null;if(error.status===401)clearState();}finally{pending=false;}}
onShow(async()=>{uni.hideTabBar({animation:false,fail:()=>{}});foreground=true;clearInterval(timer);await refresh();if(!foreground)return;await heartbeat();if(foreground)timer=setInterval(heartbeat,25000);});
onHide(()=>{foreground=false;clearInterval(timer);});
</script>
